head.b:skin:
:root { color-scheme: dark; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
* { box-sizing: border-box; }
body { min-height: 100vh; margin: 0; color: #ffffff; background: radial-gradient(circle at 16% 16%, rgba(112, 60, 255, .26), transparent 30%), radial-gradient(circle at 84% 26%, rgba(255, 60, 183, .15), transparent 28%), radial-gradient(circle at 74% 84%, rgba(0, 223, 252, .20), transparent 32%), #05060b; }
.mave-page { min-height: 100vh; display: flex; flex-direction: column; }
.mave-header { display: flex; align-items: center; padding: 24px 32px; border-bottom: 1px solid rgba(255, 255, 255, .10); background: rgba(5, 6, 11, .28); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); }
.mave-wordmark { color: #ffffff; font-family: "Neue Haas Grotesk Display Pro", Archivo, Inter, sans-serif; font-size: 24px; font-weight: 500; letter-spacing: -.03em; line-height: 1; text-shadow: 0 0 24px rgba(143, 74, 255, .42); }
.mave-content { width: min(100%, 1080px); margin: auto; padding: 80px 32px; display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(320px, .9fr); gap: 80px; align-items: center; }
.mave-intro { max-width: 620px; }
.mave-kicker { margin: 0 0 24px; color: #b6fbff; font-size: 14px; letter-spacing: .08em; text-transform: uppercase; text-shadow: 0 0 14px rgba(100, 250, 255, .42); }
h1 { margin: 0; color: #ffffff; font-family: "Neue Haas Grotesk Display Pro", Archivo, Inter, sans-serif; font-size: clamp(48px, 8vw, 88px); font-weight: 500; letter-spacing: -.055em; line-height: .96; text-shadow: 0 12px 42px rgba(0, 0, 0, .44); }
.mave-description { max-width: 440px; margin: 32px 0 0; color: rgba(255, 255, 255, .62); font-size: 17px; line-height: 1.5; }
.mave-card { position: relative; overflow: hidden; padding: 36px; border: 1px solid rgba(255, 255, 255, .16); border-radius: 20px; background: linear-gradient(145deg, rgba(255, 255, 255, .14), rgba(255, 255, 255, .045)); box-shadow: 0 32px 90px rgba(0, 0, 0, .48), inset 0 1px 0 rgba(255, 255, 255, .18), 0 0 60px rgba(0, 223, 252, .08); backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px); }
.mave-card::before { content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px; background: linear-gradient(140deg, rgba(0, 239, 255, .82), rgba(255, 255, 255, .08) 36%, rgba(255, 255, 255, .03) 60%, rgba(255, 67, 190, .74)); -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0); -webkit-mask-composite: xor; mask-composite: exclude; pointer-events: none; }
.mave-card::after { content: ""; position: absolute; width: 190px; height: 190px; right: -68px; top: 110px; border-radius: 50%; background: rgba(143, 74, 255, .20); filter: blur(60px); pointer-events: none; }
.mave-card-title { position: relative; z-index: 1; margin: 0; color: #ffffff; font-family: "Neue Haas Grotesk Display Pro", Archivo, Inter, sans-serif; font-size: 30px; font-weight: 500; letter-spacing: -.025em; line-height: 1; }
.mave-card-copy { position: relative; z-index: 1; margin: 16px 0 0; color: rgba(255, 255, 255, .62); font-size: 16px; line-height: 1.5; }
#google-button { position: relative; z-index: 1; min-height: 44px; margin: 32px 0 16px; display: flex; justify-content: center; filter: drop-shadow(0 10px 22px rgba(0, 223, 252, .16)); }
.mave-status { position: relative; z-index: 1; min-height: 24px; margin: 0; color: rgba(255, 255, 255, .62); font-size: 14px; line-height: 1.5; }
.mave-status.success { color: #86efac; }
.mave-status.error { color: #fca5a5; }
.mave-privacy { position: relative; z-index: 1; margin: 32px 0 0; padding-top: 20px; border-top: 1px solid rgba(255, 255, 255, .12); color: rgba(255, 255, 255, .40); font-size: 12px; line-height: 1.55; }
.mave-footer { display: flex; justify-content: space-between; gap: 24px; padding: 24px 32px; border-top: 1px solid rgba(255, 255, 255, .10); color: rgba(255, 255, 255, .38); font-size: 12px; background: rgba(5, 6, 11, .22); }
#mavecode-required-section { display: none; }
@media (max-width: 720px) {
	.mave-header { padding: 20px 24px; }
	.mave-content { padding: 64px 24px; grid-template-columns: 1fr; gap: 48px; }
	.mave-card { padding: 28px 24px; }
	.mave-footer { padding: 20px 24px; flex-direction: column; }
}

body.script:
//
			/*
			 * BLOGGER SETUP: replace only the PUBLIC Apps Script deployment ID below.
			 * Never paste an intake secret, provider token, session token, or private key here.
			 */
			const MAVECODE_AUTH_CONFIG = Object.freeze({
				appsScriptUrl: "https://script.google.com/macros/s/AKfycbzzh46NrOfcTOlQjl2mxmfHH5UX5Q-vtrQTbx9burYTAeYGkFUYImjX7UW6TO4NhwdU/exec",
				googleClientId: "675028173582-mihpcs5bbsk7395jiq9nctaegj9uh7ae.apps.googleusercontent.com"
			});

			(() => {
				"use strict";
				const EXACT_CALLBACK_URI = "vscode://MaveCode.mave-code/auth-callback";
				const params = new URLSearchParams(window.location.search);
				const transaction = Object.freeze({
					state: params.get("state") || "",
					codeChallenge: params.get("code_challenge") || "",
					callbackUri: params.get("callback_uri") || ""
				});
				const status = document.querySelector("#status");

				function setStatus(message, kind = "") {
					status.textContent = message;
					status.className = `mave-status ${kind}`.trim();
				}

				function validOpaque(value) {
					return /^[A-Za-z0-9_-]{43,128}$/.test(value);
				}

				function validCallback(value) {
					try {
						const callback = new URL(value);
						return callback.protocol === "vscode:"
							&& callback.hostname.toLowerCase() === "mavecode.mave-code"
							&& callback.pathname === "/auth-callback"
							&& callback.username === ""
							&& callback.password === ""
							&& callback.port === ""
							&& callback.search === ""
							&& callback.hash === ""
							&& value === EXACT_CALLBACK_URI;
					} catch {
						return false;
					}
				}

				function validPublicConfig() {
					return /^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(MAVECODE_AUTH_CONFIG.appsScriptUrl)
						&& /^[0-9]+-[A-Za-z0-9_-]+\.apps\.googleusercontent\.com$/.test(MAVECODE_AUTH_CONFIG.googleClientId);
				}

				async function completeGoogleSignIn(response) {
					try {
						if (!response || typeof response.credential !== "string" || response.credential.length < 100) throw new Error("Google did not return a valid identity token.");
						setStatus("Verifying your Google account…");
						const backend = await fetch(MAVECODE_AUTH_CONFIG.appsScriptUrl, {
							method: "POST",
							headers: { "Content-Type": "text/plain;charset=utf-8" },
							body: JSON.stringify({ action: "auth-google-complete", idToken: response.credential, ...transaction }),
							credentials: "omit",
							redirect: "follow"
						});
						const payload = await backend.json();
						if (!payload.ok) throw new Error(payload.error?.message || "This Google account is not allowed.");
						const result = payload.data;
						if (!result || result.state !== transaction.state || result.callbackUri !== transaction.callbackUri || !/^mave_code_[A-Za-z0-9_-]{20,}$/.test(result.authorizationCode || "")) throw new Error("The backend returned an invalid authorization response.");
						setStatus("Approved. Returning to MaveCode…", "success");
						const callback = new URL(result.callbackUri);
						callback.searchParams.set("code", result.authorizationCode);
						callback.searchParams.set("state", result.state);
						window.location.assign(callback.toString());
					} catch (error) {
						setStatus(error instanceof Error ? error.message : "Sign-in failed.", "error");
					}
				}

				function initialize() {
					if (!validPublicConfig()) {
						setStatus("This sign-in page has not been configured by the MaveCode administrator.", "error");
						return;
					}
					if (!validOpaque(transaction.state) || !validOpaque(transaction.codeChallenge) || !validCallback(transaction.callbackUri)) {
						setStatus("This sign-in link is invalid or incomplete. Return to VS Code and try again.", "error");
						return;
					}
					if (!globalThis.google?.accounts?.id) {
						setTimeout(initialize, 100);
						return;
					}
					google.accounts.id.initialize({ client_id: MAVECODE_AUTH_CONFIG.googleClientId, callback: completeGoogleSignIn, auto_select: false, cancel_on_tap_outside: true });
					google.accounts.id.renderButton(document.querySelector("#google-button"), { theme: "filled_blue", size: "large", shape: "pill", text: "signin_with", width: 300 });
					setStatus("Choose an approved Google account.");
				}

				initialize();
			})();
		//
